package sn.ucad.nexora.espace.presentation.mapper;
import org.springframework.stereotype.Component; import sn.ucad.nexora.espace.application.dto.response.EspaceResponse; import sn.ucad.nexora.espace.domain.entity.EspaceProfessionnel;
@Component public class EspacePresentationMapper{public EspaceResponse toResponse(EspaceProfessionnel e){EspaceResponse r=new EspaceResponse();r.setId(e.getId());r.setUtilisateurId(e.getUtilisateurId());r.setTypeEspaceId(e.getTypeEspaceId());r.setNom(e.getNom());r.setSlogan(e.getSlogan());r.setDescription(e.getDescription());r.setTelephone(e.getTelephone());r.setEmail(e.getEmail());r.setOuvert(e.isOuvert());r.setStatut(e.getStatut());r.setCertifie(e.isCertifie());r.setVerifie(e.isVerifie());r.setNoteMoyenne(e.getNoteMoyenne());r.setNombreAvis(e.getNombreAvis());r.setNombreVues(e.getNombreVues());r.setNombreFavoris(e.getNombreFavoris());r.setDateCreation(e.getDateCreation());return r;}}
